spec = {"201": ["id", "bookId", "memberId", "status"], "409": ["error"]}

def check(status, body):
    if str(status) not in spec:
        return [f"status {status} not declared"]
    return [f"missing required field {f!r}" for f in spec[str(status)] if f not in body]

