LOG_LEVELS = {"DEBUG", "INFO", "WARNING", "ERROR"}

def check(env):
    errors = []
    try:
        if not 1 <= int(env.get("LOANS_PORT", "8080")) <= 65535:
            errors.append("port range")
    except ValueError:
        errors.append("port not int")
    if env.get("LOANS_LOG_LEVEL", "INFO").upper() not in LOG_LEVELS:
        errors.append("log level")
    return errors

print(check({"LOANS_PORT": "70000", "LOANS_LOG_LEVEL": "warn"}))

